package EmployeeManagementSystem.service;
import EmployeeManagementSystem.entity.*; import EmployeeManagementSystem.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor
public class TrainingServiceImpl implements TrainingService {
 private final TrainingCourseRepository courses; private final TrainingEnrollmentRepository enrollments;
 private Map<String,Object> row(TrainingCourse c,String user){ Map<String,Object> m=new LinkedHashMap<>(); m.put("id",c.getId());m.put("title",c.getTitle());m.put("description",c.getDescription());m.put("category",c.getCategory());m.put("instructor",c.getInstructor());m.put("level",c.getLevel());m.put("durationHours",c.getDurationHours());m.put("startDate",c.getStartDate());m.put("endDate",c.getEndDate());m.put("status",c.getStatus());m.put("certificateName",c.getCertificateName()); TrainingEnrollment e=enrollments.findByCourseIdAndUserId(c.getId(),user).orElse(null); m.put("enrolled",e!=null);m.put("enrollmentStatus",e==null?null:e.getStatus());m.put("progressPercent",e==null?0:e.getProgressPercent());m.put("completedAt",e==null?null:e.getCompletedAt());m.put("certificateNumber",e==null?null:e.getCertificateNumber()); return m; }
 public List<Map<String,Object>> catalog(String u){ List<Map<String,Object>> o=new ArrayList<>(); for(TrainingCourse c:courses.findByStatusOrderByStartDateDesc("PUBLISHED"))o.add(row(c,u));return o; }
 public List<Map<String,Object>> my(String u){ List<Map<String,Object>> o=new ArrayList<>();for(TrainingEnrollment e:enrollments.findByUserIdOrderByEnrolledAtDesc(u))o.add(row(e.getCourse(),u));return o; }
 public List<TrainingCourse> all(){return courses.findAllByOrderByStartDateDesc();}
 public TrainingCourse save(TrainingCourse c){if(c.getTitle()==null||c.getTitle().isBlank())throw new IllegalArgumentException("Course title is required");if(c.getStatus()==null)c.setStatus("PUBLISHED");return courses.save(c);}
 public void delete(Long id){TrainingCourse c=courses.findById(id).orElseThrow(()->new NoSuchElementException("Course not found")); for(TrainingEnrollment e:enrollments.findByCourseIdOrderByEnrolledAtDesc(id)) enrollments.delete(e);courses.delete(c);}
 public Map<String,Object> enroll(Long id,String u,String n){TrainingCourse c=courses.findById(id).orElseThrow(()->new NoSuchElementException("Course not found")); if(enrollments.findByCourseIdAndUserId(id,u).isPresent())throw new IllegalArgumentException("Already enrolled");TrainingEnrollment e=new TrainingEnrollment();e.setCourse(c);e.setUserId(u);e.setEmployeeName(n);e.setStatus("ENROLLED");e.setProgressPercent(0);enrollments.save(e);return Map.of("success",true,"id",e.getId());}
 public Map<String,Object> progress(Long id,String u,int p){TrainingEnrollment e=enrollments.findByCourseIdAndUserId(id,u).orElseThrow(()->new NoSuchElementException("Enrollment not found"));if(p<0||p>100)throw new IllegalArgumentException("Progress must be 0-100");e.setProgressPercent(p);if(p==100){e.setStatus("COMPLETED");e.setCompletedAt(LocalDateTime.now());if(e.getCertificateNumber()==null)e.setCertificateNumber("CERT-"+e.getId()+"-"+LocalDate.now().toString().replace("-",""));}else if(!"COMPLETED".equals(e.getStatus()))e.setStatus("IN_PROGRESS");enrollments.save(e);return Map.of("success",true,"progressPercent",p,"status",e.getStatus(),"certificateNumber",e.getCertificateNumber()==null?"":e.getCertificateNumber());}
 public Map<String,Object> feedback(Long id,String u,String t){TrainingEnrollment e=enrollments.findByCourseIdAndUserId(id,u).orElseThrow(()->new NoSuchElementException("Enrollment not found"));e.setFeedback(t);enrollments.save(e);return Map.of("success",true);}
 public List<Map<String,Object>> compliance(){ List<Map<String,Object>> out=new ArrayList<>(); for(TrainingEnrollment e:enrollments.findAllByOrderByEnrolledAtDesc()){ Map<String,Object> m=new LinkedHashMap<>(); TrainingCourse c=e.getCourse(); m.put("id",e.getId());m.put("employeeName",e.getEmployeeName());m.put("userId",e.getUserId());m.put("courseId",c.getId());m.put("courseTitle",c.getTitle());m.put("category",c.getCategory());m.put("courseStatus",c.getStatus());m.put("startDate",c.getStartDate());m.put("endDate",c.getEndDate());m.put("enrollmentStatus",e.getStatus());m.put("progressPercent",e.getProgressPercent());m.put("enrolledAt",e.getEnrolledAt());m.put("completedAt",e.getCompletedAt());m.put("certificateNumber",e.getCertificateNumber()); out.add(m);} return out;}
}
